use super::*;

/// Parse `HH:MM:SS` from the head of a log line into seconds-of-day.
pub fn parse_clock(line: &str) -> Option<Clock> {
    let b = line.as_bytes();
    if b.len() < 8 || b[2] != b':' || b[5] != b':' {
        return None;
    }
    let n = |i: usize| -> Option<u32> { line.get(i..i + 2)?.parse().ok() };
    Some(n(0)? * 3600 + n(3)? * 60 + n(6)?)
}
